        return <Shell ready={this.#ready} fallback={this.fallback} preview={this.preview}><main><Card children={(slots.header = <h2>Assigned header {enabled ? <strong>Active {account.name}</strong> : <em>Pending {fallback}</em>}</h2>, enabled ? <strong>Active {account.name}</strong> : <em>Pending {fallback}</em>)}
      fallback={(slots.footer ??= <aside>Assigned footer {enabled ? <strong>Active {account.name}</strong> : <em>Pending {fallback}</em>}</aside>)}>
      {enabled && (slots.selected = <p>Selected {enabled ? <strong>Active {account.name}</strong> : <em>Pending {fallback}</em>}</p>)}
      Final visible children {count}
    </Card><footer>After assignment {account.name}</footer></main></Shell>;
      }
    }

